-- Ninth batch of explicitly labelled supplemental study outlines for MBH histology.
-- Idempotent: existing answers are never overwritten.
with supplemental_answers(id, answer) as (
  values
  ('2765df85-08f5-5865-8a4e-9d5be589699a', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Надпочечник имеет мезодермальную кору и мозговое вещество из нервного гребня. Клубочковая зона выделяет альдостерон, пучковая — кортизол, сетчатая — надпочечниковые андрогены; мозговое вещество содержит хромаффинные клетки, секретирующие адреналин и норадреналин. Кора регулируется главным образом ангиотензином II/калием для альдостерона и ACTH для кортизола; мозговое вещество — симпатической нервной системой.'),
  ('9c8dcb3e-bf44-559c-9bdc-0ae125f8f809', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Мочевая система включает почки, мочеточники, мочевой пузырь и мочеиспускательный канал. Почки фильтруют кровь и регулируют водно-солевой и кислотно-основной баланс; мочеточники проводят мочу перистальтикой, мочевой пузырь накапливает её, уретра выводит наружу. Почки развиваются из промежуточной мезодермы; эпителий большей части мочевыводящих путей связан с мочеточниковой почкой/урогенитальным синусом. Уротелий обеспечивает растяжимость и барьер.'),
  ('a5035bab-abf7-589d-9c3a-687af630545e', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эпидермис происходит из эктодермы, дерма — преимущественно из мезодермы; волосы, ногти и кожные железы развиваются из эпидермальных зачатков, взаимодействующих с дермой. Волос включает стержень, корень, фолликул и луковицу; матрикс обеспечивает рост, дермальный сосочек — трофику. Сальные железы выделяют кожное сало голокриново, потовые железы участвуют в терморегуляции и секреции. Возраст и половые гормоны меняют толщину кожи, рост волос и активность сальных желез; регенерация эпидермиса поддерживается базальными клетками.'),
  ('da2a6ed4-0ac9-50e4-8cae-fb5abe2d5003', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Стенка пищеварительного канала обычно включает слизистую (эпителий, собственная пластинка, мышечная пластинка), подслизистую, мышечную оболочку и серозу или адвентицию. Эпителий и железистые компоненты передней/средней кишки в основном происходят из энтодермы, мышцы и соединительная ткань — из мезодермы; полость рта и конечные отделы имеют эктодермальные участки. Слизистая обеспечивает защиту, секрецию и всасывание; подслизистая содержит сосуды и нервное сплетение, мышечная оболочка обеспечивает перистальтику.'),
  ('6c8b8375-8592-587f-afa5-eabb3f32f1b8', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Красный костный мозг содержит кроветворные островки, синусоидные капилляры, ретикулярную строму и макрофаги. С возрастом активный красный мозг в некоторых костях частично замещается жёлтым жировым мозгом, но при необходимости кроветворение может усиливаться. Эритропоэз проходит стадии эритробластов с постепенным уменьшением клетки, конденсацией и удалением ядра; ретикулоцит выходит в кровь и дозревает до эритроцита. Эритропоэтин почек стимулирует эритроидный рост при гипоксии.'),
  ('4ec167f8-8a07-5cad-85d6-7c958a47f9b4', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Нервная система подразделяется на центральную (головной и спинной мозг) и периферическую (нервы, ганглии, нервные окончания), а функционально — на соматическую и автономную. Нервная ткань состоит из нейронов и глии; серое вещество содержит тела нейронов и синапсы, белое — преимущественно миелиновые волокна. Нервная система принимает сенсорную информацию, интегрирует её и управляет мышцами, железами и гомеостазом.'),
  ('b02ceffb-a10e-5c13-80b2-7ecf5eed57bf', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Кора надпочечника развивается из мезодермы, мозговое вещество — из клеток нервного гребня. В коре различают клубочковую зону (минералокортикоиды), пучковую (глюкокортикоиды) и сетчатую (андрогены). Клетки пучковой зоны содержат липидные капли и развитую гладкую ЭПС; при активном стероидогенезе липидные запасы могут уменьшаться. Хромаффинные клетки мозгового вещества выделяют катехоламины под влиянием преганглионарных симпатических волокон. Секреция коры регулируется РААС и ACTH в зависимости от гормона.'),
  ('5d9f78c5-0cf9-5f7a-871c-50e2c2b9f8b9', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Околощитовидные железы развиваются из эпителия третьего и четвёртого глоточных карманов (главным образом эндодермального происхождения). Паренхима содержит главные клетки, выделяющие паратгормон, и оксифильные клетки; строма богата капиллярами и с возрастом обычно увеличивается доля жировой ткани. Паратгормон регулирует кальций и фосфат через кость, почки и косвенно кишечник. Морфологически железа отличается от щитовидной отсутствием фолликулов с коллоидом.'),
  ('064e5c97-840d-544d-81bd-b2103d692204', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Органы чувств включают рецепторные клетки, вспомогательные структуры и нервные пути. Обонятельные нейроны — биполярные клетки эпителия обонятельной области; их реснички несут рецепторы запахов. В сетчатке фоторецепторы (палочки и колбочки) преобразуют свет в электрический сигнал; далее сигнал проходит через биполярные и ганглиозные клетки. Палочки обеспечивают сумеречное зрение, колбочки — цветовое и высокую остроту. Поддерживающие клетки и пигментный эпителий обеспечивают трофику и обслуживание фоторецепторов.'),
  ('4ee3d7ca-b69f-5ed9-b84f-c50b20659a95', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Вкусовые почки расположены в эпителии грибовидных, листовидных и желобоватых сосочков языка; нитевидные сосочки вкусовых почек обычно не имеют. В почке есть вкусовые сенсорные, поддерживающие и базальные клетки; апикальные микроворсинки контактируют с растворёнными веществами через вкусовую пору. Клетки обновляются из базальных предшественников. Вкусовая информация проводится через лицевой, языкоглоточный и блуждающий нервы в зависимости от области языка и глотки.'),
  ('2939703c-a685-5f50-a26c-79e8d22378db', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Улитковый канал заполнен эндолимфой и ограничен вестибулярной и базилярной мембранами; на базилярной мембране расположен кортиев орган. Он содержит внутренние и наружные волосковые клетки и поддерживающие клетки; стереоцилии контактируют с текторной мембраной или движутся относительно неё. Звуковые колебания перемещают базилярную мембрану, отклоняют волоски и преобразуются в нервный сигнал. Афферентная иннервация идёт через спиральный ганглий и кохлеарную часть VIII нерва.'),
  ('f1463aa0-f319-5b4d-a3ee-ca7a80e24ad1', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Вестибулярный аппарат включает маточку и мешочек с пятнами (макулами), а также ампулы полукружных каналов с гребешками. Сенсорные волосковые клетки имеют стереоцилии и киноцилиум (в зависимости от типа/стадии), погружённые в отолитовую мембрану или купулу; смещение волосков меняет частоту импульсов афферентных волокон. Пятна воспринимают линейное ускорение и положение головы относительно силы тяжести, ампулярные гребешки — угловое ускорение. Иннервация идёт через вестибулярную часть VIII черепного нерва.'),
  ('93aed4eb-1459-5f73-b310-2cbc5e839772', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Мочеточник имеет слизистую с переходным эпителием и складчатой собственной пластинкой, мышечную оболочку из гладких миоцитов и наружную адвентицию; перистальтика продвигает мочу. Мочевой пузырь выстлан уротелием с зонтичными клетками, имеет мощную мышечную оболочку (детрузор) и наружную адвентицию/серозу в отдельных участках. Уретра отличается по отделам и полу, эпителий постепенно меняется от переходного к цилиндрическому и многослойному плоскому. Иннервация автономная, а мочеиспускание контролируется также соматическими механизмами.'),
  ('0f47c1ba-07fd-5949-a5ee-b273ac0ff7b5', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Нефрон включает почечное тельце (капиллярный клубочек и капсулу Боумена), проксимальный каналец, петлю Генле и дистальный каналец; далее моча поступает в собирательные трубочки. Фильтрационный барьер состоит из фенестрированного эндотелия клубочковых капилляров, общей базальной мембраны и щелевых диафрагм между ножками подоцитов. Он пропускает воду и малые молекулы, но задерживает клетки крови и большинство крупных белков. Мезангиальные клетки поддерживают клубочек и регулируют площадь фильтрации.'),
  ('e76d113d-bd82-562f-8042-5a403f9c3e11', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Мочеточник выстлан переходным эпителием, слизистая образует продольные складки; мышечные слои обеспечивают перистальтику. Мочевой пузырь имеет уротелий, собственную пластинку и толстую мышцу детрузор из переплетающихся пучков гладких миоцитов. При наполнении зонтичные клетки распластываются, а плотные контакты сохраняют непроницаемость для мочи. Наружная оболочка — адвентиция, кроме участков, покрытых серозой.'),
  ('6327af61-782f-5643-8306-90a3bcd940b0', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Пульпа — мягкая соединительная ткань зуба с фибробластами, иммунными клетками, сосудами, нервами и периферическим слоем одонтобластов. Кровеносные сосуды и нервные пучки входят через апикальное отверстие; коронковая пульпа имеет более крупную камеру и рога, корневая — узкие каналы. Одонтобласты образуют вторичный и третичный дентин, но регенерация ограничена. С возрастом полость пульпы сужается, увеличивается фиброз и могут появляться дентикли.'),
  ('bcdf4e68-c5cf-5d47-abd6-7de4b440ff8d', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Мягкое нёбо содержит поперечно-полосатые скелетные мышцы, соединительную ткань, сосуды, нервы и слизистые железы. Ротовая поверхность обычно покрыта многослойным плоским неороговевающим эпителием; носоглоточная поверхность может иметь многорядный реснитчатый эпителий дыхательного типа. Язычок является продолжением мягкого нёба и содержит мышечные пучки и слизистые железы. Различие поверхностей связано с механической нагрузкой и функцией проведения воздуха/пищи.'),
  ('b7945fa6-5b87-5f9a-bef1-a8c8b37ab93e', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Околоушная железа развивается из эпителиального зачатка полости рта; паренхима преимущественно серозная. Серозные ацинусы состоят из пирамидальных клеток с базофильной базальной частью и апикальными секреторными гранулами. Протоковая система включает вставочные, исчерченные и междольковые выводные протоки; исчерченные протоки модифицируют электролитный состав слюны. В строме часто встречаются жировые клетки, особенно с возрастом.'),
  ('7cc82d0e-1794-5e08-a785-5116d94fc41e', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Чувствительные ганглии содержат тела псевдоуниполярных нейронов, окружённые клетками-сателлитами и соединительнотканной капсулой. Они развиваются преимущественно из нервного гребня. Периферический отросток воспринимает сигнал от рецептора, центральный входит в ЦНС; в типичном чувствительном ганглии синапсов между нейронами нет. В рефлекторной дуге чувствительный нейрон передаёт импульс в спинной мозг или ствол мозга, где сигнал переключается на вставочные и/или двигательные нейроны.'),
  ('99afe8ef-ece6-57d9-a93b-a5dd505e07b0', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Глаз развивается из нейроэктодермы (сетчатка, часть сосудистых структур), поверхностной эктодермы (хрусталик, эпителий роговицы) и мезенхимы/нервного гребня (склера, строма роговицы и сосудистые оболочки). Роговица прозрачна, состоит из эпителия, боуменовой мембраны, стромы, десцеметовой мембраны и эндотелия; склера плотная коллагеновая. Хрусталик прозрачен и лишён сосудов. Диоптрический аппарат включает роговицу и хрусталик; аккомодация осуществляется изменением кривизны хрусталика цилиарной мышцей.')
)
update public.exam_questions q
set answer = s.answer, updated_at = now()
from supplemental_answers s
where q.id = s.id::uuid
  and q.subject_slug = 'histology'
  and nullif(btrim(q.answer), '') is null;
